local E = ns.DB.entries
E["npc:altsoba-ragetotem"] = {t="npc",n="Altsoba Ragetotem",z="felwood",s="Altsoba Ragetotem is a tauren weaponsmith stationed at Bloodvenom Post in Felwood. From this remote Horde outpost, he keeps passing champions armed with reliable maces, staves, and axes to face the blighted horrors of the forest.",h="Altsoba Ragetotem is a tauren weaponsmith stationed at Bloodvenom Post in Felwood.",sec={{t="Armorer of Bloodvenom Post",b="Bloodvenom Post is a treacherous outpost, situated in the heart of Felwood amidst demonic corruption and tainted wildlife. Maintaining a supply line out here is a grim necessity, and Altsoba Ragetotem does his part by outfitting Horde scouts and travelers. Whether someone requires a sturdy crescent axe or a heavy war maul, Altsoba ensures warriors heading into the corrupted timberlands do not enter the fray unarmed.",sp=0}},faq={{q="Who is Altsoba Ragetotem?",a="Altsoba Ragetotem is a tauren vendor stationed at Bloodvenom Post, the Horde encampment in Felwood. He provides basic heavy weaponry to travelers and defenders braving the blighted valley.",al={"who is altsoba","altsoba ragetotem","tauren at bloodvenom post"}},{q="What does Altsoba sell?",a="He sells a variety of standard melee weapons, including battle staves, morning stars, war mauls, and axes, offering dependable steel for adventurers venturing deep into Felwood.",al={"altsoba wares","altsoba vendor items","what weapons does altsoba sell"}},{q="Where can I find Altsoba Ragetotem?",a="He can be found resting within Bloodvenom Post, perched along the cliffs overlooking the foul waters and tainted glades of Felwood.",al={"altsoba location","where is altsoba","bloodvenom post vendor location"}}},ang={["faction:Horde"]="Altsoba provides essential martial supplies to Horde operatives holding their ground in one of Kalimdor's most corrupted regions.",["race:Tauren"]="As a member of the Ragetotem tribe, Altsoba brings traditional tauren steadfastness to a land suffering profoundly under demonic blight."},kw={"altsoba","bloodvenom post","felwood","ragetotem","tauren","vendor","weaponsmith"},rel={"subzone:bloodvenom-post","zone:felwood","topic:tauren"},src={"Altsoba Ragetotem"}}
E["npc:greta-mosshoof"] = {t="npc",n="Greta Mosshoof",z="felwood",s="Greta Mosshoof is a tauren druid allied with the Emerald Circle at the Emerald Sanctuary in southern Felwood. Alongside night elves and fellow guardians of nature, she investigates the foul taint creeping across the ancient forest and directs scouts into the Shadow Council stronghold of Jaedenar.",h="Greta Mosshoof is a tauren druid allied with the Emerald Circle at the Emerald Sanctuary in southern Felwood.",sec={{t="Guardian of the Forest",b="Stationed at the Emerald Sanctuary on the southern boundary of Felwood, Greta Mosshoof works alongside the Emerald Circle to combat the pervasive corruption consuming the ancient woods. Rather than surrendering the blighted lands to the demonic taint left in the wake of the Third War, she coordinates efforts to understand and push back the spreading rot. Her investigations zero in on the poisoned waters of Felwood and the foul cultists burrowed within Jaedenar.",sp=0},{t="Striking at the Shadow Council",b="Greta Mosshoof is instrumental in uncovering the machinations of the Shadow Council operating from the depths of Jaedenar. Recognizing that the corrupted springs and foul wards in the chasm directly feed the sickness choking the land, she enlists travelers to sample the tainted waters, seek the assistance of shamans like Islen Waterseer on the distant coast, and dismantle the ritual braziers that protect the demonic cabal from intrusion.",sp=1}},faq={{q="Who is Greta Mosshoof?",a="Greta Mosshoof is a tauren member of the Emerald Circle stationed at the Emerald Sanctuary in Felwood. She aids travelers and druids in investigating and undoing the demonic blight poisoning the forest.",al={"greta mosshoof lore","who is greta mosshoof","greta felwood"}},{q="What faction does Greta Mosshoof belong to?",a="Greta Mosshoof is a member of the Emerald Circle, a neutral organization dedicated to healing nature. As such, she offers guidance and quests to both Alliance and Horde adventurers.",al={"is greta mosshoof horde or alliance","greta mosshoof reputation","greta faction"}},{q="Why is Greta sending adventurers into Jaedenar?",a="Jaedenar is the stronghold of the Shadow Council in Felwood, responsible for pumping demonic bile into the land's waterways and maintaining wards that shelter demons. Greta directs strikes against Jaedenar to dismantle their rituals and purify the blighted springs.",al={"why jaedenar quest","greta mosshoof jaedenar","forces of jaedenar reason"}},{q="What is Greta Mosshoof's connection to Islen Waterseer?",a="Greta is friends with Islen Waterseer, a wise shaman residing along the coast of the Barrens. When Greta discovers corrupt water samples from Felwood, she directs adventurers to seek Islen's spiritual mastery to purify the fluid so it can cleanse the poisoned springs.",al={"greta and islen","islen waterseer connection"}}},ang={["class:Druid"]="For druids working to purge the scars of the Burning Legion, Greta Mosshoof represents the cooperative spirit of the Cenarion circle, setting aside faction ties to restore Kalimdor's wilderness.",["race:Tauren"]="Greta demonstrates the dedication of the tauren to healing the Earth Mother's wounds, even far to the north in lands once guarded solely by the night elves."},kw={"corrupt water","emerald circle","emerald sanctuary","felwood","greta mosshoof","islen waterseer","jaedenar"},rel={"subzone:emerald-sanctuary","zone:felwood","subzone:jaedenar","npc:islen-waterseer","topic:tauren"},src={"Greta Mosshoof"}}
E["npc:kelnir-leafsong"] = {t="npc",n="Kelnir Leafsong",z="felwood",s="Kelnir Leafsong is a dryad found standing along the thoroughfare east of Bloodvenom Post in Felwood. Like her sisters throughout Kalimdor, she watches over the corrupted woodland, monitoring the blighted surroundings and the nearby encampments that exploit or threaten what remains of nature.",h="Kelnir Leafsong is a dryad found standing along the thoroughfare east of Bloodvenom Post in Felwood.",sec={{t="A Watcher on the Corrupted Road",b="Daughters of Cenarius, dryads are intrinsically tied to the well-being of the wild. In Felwood, where demonic taint and rotting ichor choke every copse, their vigilance is tested to its absolute limit. Kelnir Leafsong stands alongside the main trail near the tauren Altsoba Ragetotem, keeping watch over both the polluted wilderness and the encroaching presence of Bloodvenom Post to the west. Her focus lies in curbing the vile slimes and hazards that seep into the soil and directing allies toward safer sanctuaries like Whisperwind Grove.",sp=0}},faq={{q="Who is Kelnir Leafsong?",a="Kelnir Leafsong is a dryad, one of the nature-bound daughters of the demigod Cenarius. She is stationed along the road in central Felwood to observe the surrounding corruption and assist travelers trying to survive or cleanse the tainted woods.",al={"who is kelnir","kelnir leafsong lore","who is the dryad near bloodvenom post"}},{q="Why is Kelnir stationed so close to Bloodvenom Post?",a="She keeps a close eye on the region around the Forsaken and Horde encampment at Bloodvenom Post, where the festering rot, slime hazards, and local wildlife pose constant danger to the forest's fragile balance.",al={"why near bloodvenom post","kelnir location felwood","what is she watching"}},{q="What is Kelnir's connection to Whisperwind Grove?",a="Whisperwind Grove serves as a central night elf haven and sanctuary for natural guardians in northern Felwood. Kelnir acts as a roadside contact who guides wanderers toward the grove away from the tainted lowlands.",al={"kelnir whisperwind grove","whisperwind connection"}}},ang={["class:Druid"]="As a daughter of Cenarius, Kelnir embodies the sacred kinship druids hold with the wild, striving to contain the vile slimes and blighted corruption choking Felwood's roots.",["race:NightElf"]="For night elves traveling the blighted roads of Felwood, Kelnir offers a familiar, reassuring ally dedicated to guarding the woods and directing travelers toward Whisperwind Grove."},kw={"altsoba ragetotem","bloodvenom post","cenarius daughter","dryad","felwood","kelnir leafsong","whisperwind grove"},rel={"zone:felwood","subzone:bloodvenom-post","npc:altsoba-ragetotem"},src={"Kelnir Leafsong"}}
E["npc:winna-hazzard"] = {t="npc",n="Winna Hazzard",z="felwood",s="Winna Hazzard is an eccentric Forsaken researcher stationed at Bloodvenom Post in Felwood. Accompanied by a feline companion and known for bouts of maniacal laughter, she studies the blighted ecosystem and conducts unsettling experiments with the zone's corrupted fauna.",h="Winna Hazzard is an eccentric Forsaken researcher stationed at Bloodvenom Post in Felwood.",sec={{t="A Peculiar Researcher",b="Winna Hazzard represents the Forsaken interest in Felwood's unnatural decay. Stationed in the Horde enclave of Bloodvenom Post, she spends her time observing the local wildlife and formulating experiments utilizing tainted waters and venomous samples. Her jovial, manic demeanor often masks callous motives, evident when she uses tainted liquids drawn from the land to corrupt the small kitten that stays by her side.",sp=0}},faq={{q="Who is Winna Hazzard?",a="Winna Hazzard is a Forsaken questgiver located at Bloodvenom Post in north-central Felwood. She investigates Felwood's corrupting influences and tasks adventurers with collecting samples from the wilderness.",al={"winna hazzard","who is winna","felwood cat lady"}},{q="What happens to her kitten?",a="When adventurers bring Winna a filled flasket of corrupted liquid from the surrounding woods, she feeds it directly to her pet kitten, mutating the creature into a Corrupted Cat before laughing maniacally.",al={"winna kitten","corrupted cat","felwood cat experiment"},sp=1},{q="What is Winna Hazzard's goal in Felwood?",a="Like many Forsaken apothecaries and scholars, Winna seeks to understand and harness biological blights, using Felwood's pervasive corruption to study how it alters and twists living beasts.",al={"winna hazzard motive","why is winna in felwood"}}},ang={["race:Undead"]="Winna embodies the darker eccentricities of the Forsaken, displaying reckless curiosity toward corruption without regard for natural harmony.",["faction:Horde"]="Stationed safely at Bloodvenom Post, Winna enlists passing Horde travelers to gather corrupted reagents for her bizarre research."},kw={"bloodvenom post","felwood","forsaken","kitten","winna hazzard"},rel={"subzone:bloodvenom-post","zone:felwood","topic:forsaken","npc:altsoba-ragetotem"},src={"Winna Hazzard"}}
E["npc:xavathras"] = {t="npc",n="Xavathras",z="felwood",s="Xavathras is a vicious satyr commander residing among the tents at the Ruins of Constellas in Felwood. Leading a band of Jadefire satyrs, he oversees the corruption of an ancient moonwell in service to his master, Xavaric.",h="Xavathras is a vicious satyr commander residing among the tents at the Ruins of Constellas in Felwood.",sec={{t="Corruptor of Constellas",b="Within the tainted glades of Felwood, the Ruins of Constellas have fallen into the clutches of the Jadefire satyrs. Stationed in an encampment pitched amidst the elven stonework, Xavathras directs the defilement of a nearby moonwell on behalf of another cruel satyr, Xavaric. By poisoning the pure waters with demonic energy, Xavathras deepens the corruption that grips the forest. His presence poses a direct threat to any attempts to restore the woodland, earning the ire of night elves like Arcanist Delaris who mark him for death.",sp=0}},faq={{q="Who is Xavathras?",a="Xavathras is a cruel satyr leader who commands the Jadefire satyrs entrenched in the Ruins of Constellas within Felwood. He serves Xavaric and is tasked with corrupting the ancient elven moonwell located among the ruins.",al={"who is xavathras","xavathras lore","who is the satyr boss constellas"}},{q="Where can Xavathras be found?",a="Xavathras makes his camp among the satyr tents at the Ruins of Constellas, an ancient night elf site located in southern-central Felwood.",al={"xavathras location","where is xavathras","ruins of constellas satyr"}},{q="Why does Arcanist Delaris want Xavathras dead?",a="Arcanist Delaris seeks to defend Felwood and halt the rampant spread of demonic defilement. Xavathras is actively cultivating a corrupted moonwell, making his elimination a top priority for those attempting to cleanse the land.",al={"why kill xavathras","delaris xavathras"}},{q="Who is Xavathras working for?",a="Xavathras works on behalf of Xavaric, another cruel and powerful satyr operating within Felwood to further the Legion's lingering grasp on the corrupted forest.",al={"who is xavathras master","xavaric xavathras"}}},ang={["race:NightElf"]="For night elves, Xavathras represents the tragedy of their ancient kin turned demonic beasts, as well as an active desecrator of their sacred moonwells.",["class:Druid"]="Druids seeking to undo the demonic blighting of Felwood view Xavathras's deliberate poisoning of pure waters as an affront to nature that must be stopped."},kw={"constellas","delaris","felwood","jadefire","moonwell","satyr","xavaric","xavathras"},rel={"subzone:ruins-of-constellas","zone:felwood","topic:satyr","subzone:moonwell-ashenvale","quest:6921"},src={"Xavathras"}}
E["subzone:bloodvenom-falls"] = {t="subzone",n="Bloodvenom Falls",z="felwood",s="Bloodvenom Falls is a towering, foul waterfall plunging down the corrupted cliffs of northern Felwood. Its toxic flow feeds the Bloodvenom River, spreading demon-spawned rot down the mountains and into downstream lands.",h="Bloodvenom Falls is a towering, foul waterfall plunging down the corrupted cliffs of northern Felwood.",sec={{t="A Fountain of Rot",b="Pouring over the bluffs in Felwood, Bloodvenom Falls represents one of the most vivid wounds inflicted upon the ancient forests of Kalimdor. Once a pristine mountain cascade, the waters were warped into a virulent sludge during the Third War by demonic magics and the remnants of the Burning Legion. The falls feed directly into the Bloodvenom River, which weaves through the heart of Felwood. From there, the tainted torrent rushes down the mountain slopes to become the foul Wildbend River in Darkshore, carrying blight far beyond Felwood's blighted borders.",sp=0},{t="Ecological Poison",b="The virulent runoff from Bloodvenom Falls does not merely discolor the riverbed; it warps everything it touches. The swampy banks surrounding its spray breed twisted treants, sickening beasts, and aggressive slimes. For druids and wardens attempting to contain Felwood's rot, the falls are a chilling reminder that northern Kalimdor's waters remain deeply sickened at their source.",sp=0}},faq={{q="Where does the water from Bloodvenom Falls flow?",a="The falls feed directly into the Bloodvenom River. The river cuts across Felwood before cascading down the mountains into Darkshore, where it becomes the corrupted Wildbend River.",al={"where does bloodvenom river go","bloodvenom falls river path","where does it drain"}},{q="Why is the waterfall corrupted?",a="During the Third War, the Burning Legion's demonic magic saturated the region, corrupting the wild forests of Felwood. The springs and high mountain streams feeding the falls absorbed this fel blight, transforming the water into toxic muck.",al={"why is bloodvenom falls green","why is the water poisoned","what corrupted bloodvenom falls"}},{q="Does the corruption at the falls affect other zones?",a="Yes. The waters plunge from Felwood down the western mountain crests into Darkshore, emerging as the contaminated Wildbend River and spreading rot toward the coast.",al={"does felwood poison darkshore","how does it affect darkshore","darkshore river pollution"}},{q="Can the waters of Bloodvenom Falls be purified?",a="The Cenarion Circle continues to seek ways to cleanse Felwood, but the sheer volume and deep saturation of demonic taint in the river makes curing the falls a monumental struggle that remains unresolved.",al={"can druids fix bloodvenom falls","is bloodvenom falls cleansable","cleaning the waterfall"}}},ang={["class:Druid"]="The polluted plunge of Bloodvenom Falls is a bitter sight for the Cenarion Circle, serving as a primary conduit carrying Felwood's vile sickness into the lands below.",["race:NightElf"]="For night elves, the sight of Bloodvenom Falls feeding the poisoned Wildbend River in Darkshore is a direct threat to ancestral homes and coastal sanctuaries."},kw={"bloodvenom falls","bloodvenom river","corruption","darkshore","felwood","slime","waterfall","wildbend river"},rel={"subzone:bloodvenom-river","subzone:wildbend-river","zone:felwood","zone:darkshore"},src={"Bloodvenom Falls"}}
E["subzone:bloodvenom-post"] = {t="subzone",n="Bloodvenom Post",z="felwood",s="Bloodvenom Post is a remote Horde settlement perched on the rocky bluffs of western Felwood overlooking Darkshore. Founded and maintained largely by tauren scouts, it serves as the Horde's solitary foothold in a region infested with demonic taint and corrupted wildlife.",h="Bloodvenom Post is a remote Horde settlement perched on the rocky bluffs of western Felwood overlooking...",sec={{t="A Precarious Foothold",b="Tucked away along the high cliffs above Darkshore, Bloodvenom Post is reached by following the corrupted southern bank of the Bloodvenom River away from Felwood's main thoroughfare. Built with traditional tauren tents, totems, and watch posts, this encampment provides Horde wanderers with a vital base of operations amidst a dying forest. From here, scouts track the encroaching demonic forces, study the spreading corruption of the waters, and attempt to monitor the hostile wildlife mutated by the Burning Legion's lingering power.",sp=0},{t="Eyes Across the Ridge",b="Beyond observing the tainted wilds of Felwood, the camp sits right upon the precipice peering down over northern Darkshore. Its isolated position serves a double duty: keeping Horde forces informed of night elf movements along the western coastline while remaining well out of easy reach of Alliance patrols traversing the forest's central road.",sp=0}},faq={{q="Where is Bloodvenom Post located?",a="Bloodvenom Post is hidden along the western ridges of central Felwood. To reach it from the main north-south road, follow the southern bank of the Bloodvenom River westward along a narrow trail that curves around the rocky hillside.",al={"find bloodvenom post","how to get to bloodvenom post","bloodvenom post directions"}},{q="Who controls this outpost?",a="Bloodvenom Post is an outpost of the Horde, largely established and protected by tauren scouts and braves seeking to monitor Felwood's corruption.",al={"who runs bloodvenom post","bloodvenom post faction"}},{q="Why is the post named Bloodvenom?",a="It takes its name from the adjacent Bloodvenom River, whose waters have been fouled and turned toxic by demonic corruption seeped into the forest.",al={"why bloodvenom","bloodvenom name meaning"}},{q="What threats do the scouts face here?",a="The post faces continuous pressure from the corrupted wildlife native to Felwood, including rabid sabers, tainted oozes, and twisted treants, along with the demonic presence of the Shadow Council and Burning Legion remnants throughout the zone.",al={"bloodvenom enemies","what attacks bloodvenom post"}}},ang={["faction:Horde"]="As the Horde's only fortified respite in Felwood, this camp offers safety, shelter, and a base of operations within an otherwise thoroughly hostile wilderness.",["race:Tauren"]="Tauren braves maintain this post to study the environmental devastation wrought by the Legion and to counter the corruption destroying the land's natural spirits."},kw={"bloodvenom post","bloodvenom river","darkshore cliffs","felwood","horde outpost","tauren"},rel={"subzone:bloodvenom-river","zone:felwood","topic:tauren","topic:horde","zone:darkshore"},src={"Bloodvenom Post"}}
E["subzone:bloodvenom-river"] = {t="subzone",n="Bloodvenom River",z="felwood",s="The Bloodvenom River is a foul waterway cutting through central Felwood, saturated with the demonic corruption that blighted the ancient forest. Its putrid waters seep downstream across the mountains into Darkshore, transforming into the tainted Wildbend River.",h="The Bloodvenom River is a foul waterway cutting through central Felwood, saturated with the demonic...",sec={{t="A Vein of Corruption",b="Running through the corrupted heart of Felwood, the Bloodvenom River serves as an open conduit of the land's spiritual and physical decay. Its banks are thick with vile oozes, mutated beasts, and foul run-off left in the wake of the Burning Legion's invasion. The corruption within the channel is potent enough to taint lands far beyond Felwood itself, flowing westward down into the coastal forests of Darkshore as the Wildbend River.",sp=0}},faq={{q="Why is the river corrupted?",a="The river runs through central Felwood, an ancient night elven forest deeply warped by the demonic magic of the Burning Legion during the Third War. The corruption thoroughly soaked into the land and its waters, turning the river into a conduit of noxious sludge and necrotic ooze.",al={"bloodvenom river taint","why is the water green","felwood river poison"}},{q="Where does the Bloodvenom River flow?",a="The river flows through the tainted valley of Felwood before spilling through the mountains into Darkshore. Beyond the ridge, its corrupted currents continue downstream under the name of the Wildbend River.",al={"bloodvenom river path","where does it go","river to darkshore"}},{q="What creatures live along the riverbanks?",a="The waters and muddy banks are inhabited by noxious oozes, warped wildlife, and corrupted predators drawn to or created by the virulent demonic blight.",al={"bloodvenom river wildlife","mobs near bloodvenom river","monsters in the river"}}},ang={["class:Druid"]="The Bloodvenom River is a glaring testament to the desecration of Kalimdor's sacred groves, carrying fel taint across regions and demanding nature's restoration.",["race:NightElf"]="For the kaldorei, watching the waters of their ancestral woodland poison Darkshore via the Wildbend River is a bitter reminder of the Legion's lingering wound."},kw={"bloodvenom river","corruption","darkshore","felwood","ooze","tainted water","wildbend river"},rel={"zone:felwood","subzone:wildbend-river","zone:darkshore"},src={"Bloodvenom River"}}
E["subzone:deadwood-village"] = {t="subzone",n="Deadwood Village",z="felwood",s="Deadwood Village is a furbolg encampment nestled in southern Felwood. Once a peaceful clan attuned to nature, its residents fell victim to the demonic corruption that blighted the surrounding forest. Driven mad by fel taint, the Deadwood furbolgs now attack anyone who approaches their crude wooden settlement.",h="Deadwood Village is a furbolg encampment nestled in southern Felwood.",sec={{t="A Fallen Tribe",b="Situated near the southern border of Felwood, Deadwood Village serves as the primary enclave of the Deadwood tribe. When the Burning Legion's demonic energies washed through the ancient woodlands, the furbolgs lacked the power to resist the creeping rot. Their minds warped by fel malice, they abandoned their ancient traditions and spiritual harmony. Today, the village is a squalid gathering of hostile brutes, shamans, and den watchers who violently defend their polluted grounds against intruders, earning the despair of their uncorrupted cousins, the Timbermaw.",sp=0}},faq={{q="Why are the furbolgs here hostile?",a="The furbolgs of Deadwood Village were overwhelmed by the demonic corruption that ruined Felwood during the Third War. The fel magic warped their natural instincts into rabid aggression, driving them violently insane and hostile to all outsiders.",al={"deadwood hostility","why attack","why are deadwood red"}},{q="Can players talk to or make peace with Deadwood Village?",a="No. The Deadwood tribe is thoroughly corrupted beyond peaceful diplomacy. Instead, adventurers hunt them to collect tribal feathers and gain favor with the uncorrupted Timbermaw furbolgs guarding the tunnels to the north.",al={"can you be friendly with deadwood","deadwood reputation"}},{q="How does this tribe relate to the Timbermaw?",a="Both were once typical furbolg tribes living in harmony with nature. When Felwood was corrupted, the Timbermaw tribe managed to preserve their sanity, while the Deadwood tribe succumbed entirely to fel madness. The Timbermaw now consider the Deadwood fallen and dangerous.",al={"timbermaw and deadwood","furbolg tribes"}}},ang={["class:Druid"]="Deadwood Village represents a heartbreaking failure of nature's defense, reminding Cenarion druids of how deeply demonic corruption can twist peaceful creatures."},kw={"corruption","deadwood","deadwood village","felwood","furbolg","ruumbo","timbermaw"},rel={"zone:felwood","topic:furbolg"},src={"Deadwood Village"}}
E["subzone:emerald-sanctuary"] = {t="subzone",n="Emerald Sanctuary",z="felwood",s="The Emerald Sanctuary is an outpost of the Cenarion Circle situated at the southern entrance of Felwood. Here, night elven and tauren druids unite to study the pervasive demonic taint and attempt the arduous task of healing the corrupted woodland.",h="The Emerald Sanctuary is an outpost of the Cenarion Circle situated at the southern entrance of Felwood.",sec={{t="A Beacon in the Blight",b="Perched on the southern edge of Felwood near the Ashenvale border, the Emerald Sanctuary serves as the primary base of operations for the Cenarion Circle in this blighted wilderness. Unlike the bitter factional conflicts burning across Kalimdor, this sanctuary offers a neutral foothold where druids look past politics to focus entirely on ecological restoration. From here, researchers track corrupted flora and direct investigations toward Jaedenar, seeking any viable method to cleanse the poisoned soil.",sp=0}},faq={{q="What is the purpose of the Emerald Sanctuary?",a="The Cenarion Circle established the camp to study and counter the demonic taint choking Felwood. Druids stationed here investigate corrupted plants, beasts, and water sources while coordinating efforts to combat the Shadow Council cultists entrenched deeper in the woods.",al={"why is emerald sanctuary here","what do druids do here","emerald sanctuary purpose"}},{q="Can both Alliance and Horde visit the Emerald Sanctuary?",a="Yes. The Cenarion Circle operates as an independent, neutral organization. Both Alliance and Horde adventurers are welcomed so long as they are willing to assist in cleansing Felwood's deep corruption.",al={"is emerald sanctuary neutral","horde allowed emerald sanctuary","alliance sanctuary friendly"}},{q="What threat concerns the druids here the most?",a="While the entire forest is warped by demonic energies left behind after the Third War, the druids are especially alarmed by Jaedenar, a sprawling cavern complex to the north where the Shadow Council actively festers and spreads corruption.",al={"biggest threat in felwood","what are druids fighting","jaedenar threat"}}},ang={["class:Druid"]="For druids of both Darnassus and Thunder Bluff, the Emerald Sanctuary is a crucial reminder of their shared calling, demonstrating that the mandate to heal the land transcends worldly faction loyalties."},kw={"cenarion circle","corruption","druids","emerald sanctuary","felwood","jaedenar"},rel={"zone:felwood","subzone:jaedenar","subzone:talonbranch-glade","subzone:bloodvenom-post","topic:druid"},src={"Emerald Sanctuary"}}
E["subzone:felpaw-village"] = {t="subzone",n="Felpaw Village",z="felwood",s="Felpaw Village is a corrupted furbolg settlement nestled in the far northern reaches of Felwood, guarding the mountain path leading directly to Timbermaw Hold. Inhabited by the fallen Deadwood tribe, its huts and gathering grounds are tainted by demonic influence and hostile to all outsiders.",h="Felpaw Village is a corrupted furbolg settlement nestled in the far northern reaches of Felwood, guarding the...",sec={{t="A Stronghold of Corruption",b="Situated at the northern edge of Felwood, Felpaw Village serves as the primary northern redoubt for the fallen Deadwood furbolgs. Once gentle forest wardens, the tribe fell victim to the demonic blight unleashed during the Third War, driving them into a state of feral madness. Now, the village stands as a blighted enclave filled with crude huts, ritual totems, and hostile warriors who attack anyone wandering near the tunnel entrance to Timbermaw Hold.",sp=0},{t="A Thorn Beside Timbermaw Hold",b="The proximity of Felpaw Village to the sacred entrance of Timbermaw Hold makes it a critical threat to the few uncorrupted furbolgs remaining in the region. The Timbermaw guards posted at the northern mouth of Felwood view their fallen cousins with a mixture of mourning and vigilance, frequently calling upon travelers to cull the Deadwood ranks, seize their ritual fetishes, and keep the corruption from spilling through the gates into Moonglade and Winterspring.",sp=0}},faq={{q="Who lives in Felpaw Village?",a="The settlement belongs to the Deadwood furbolgs, a local tribe that has fallen completely under the sway of demonic corruption spreading across Felwood.",al={"felpaw village inhabitants","who is at felpaw","deadwood furbolgs northern felwood"}},{q="Why are the furbolgs here hostile?",a="The Deadwood furbolgs were driven completely mad by the demonic energies poisoning the soil, water, and wildlife of Felwood. They see all outsiders as enemies and cannot be reasoned with.",al={"why do deadwood attack","are felpaw furbolgs friendly","why are bears angry felwood"}},{q="Where is Felpaw Village located?",a="It lies at the far northern end of Felwood, right along the road leading up to the main southern entrance of Timbermaw Hold.",al={"felpaw village map location","where is felpaw village","how to get to felpaw"}},{q="How does Felpaw Village relate to Timbermaw Hold?",a="The uncorrupted Timbermaw tribe watches Felpaw Village closely from their nearby gates. Because the Deadwood threaten the safety of the passage between Felwood, Winterspring, and Moonglade, the Timbermaw reward outsiders who thin the village's hostile ranks and recover Deadwood ritual feathers.",al={"timbermaw connection","timbermaw hold reputation felpaw","timbermaw deadwood"}}},ang={["class:Druid"]="For druids dedicated to restoring the natural order, the fallen Deadwood of Felpaw Village are a tragic reminder of the Legion's lingering poison in sacred forests.",["race:NightElf"]="The Night Elves once counted the furbolgs as steadfast allies, making the sight of the Deadwood's madness and ritualistic debasement at Felpaw especially bitter."},kw={"corruption","deadwood","felpaw","felpaw village","felwood","furbolg","timbermaw"},rel={"zone:felwood","subzone:timbermaw-hold","topic:furbolg"},src={"Felpaw Village"}}
E["subzone:irontree-woods"] = {t="subzone",n="Irontree Woods",z="felwood",s="Irontree Woods is a blighted grove situated in northern Felwood, once cherished by the night elves as a peaceful forest sanctuary. Ravaged by the demonic corruption of the Third War, its ancient protectors have been petrified into stone while twisted treants and elementals prowl among the ruins.",h="Irontree Woods is a blighted grove situated in northern Felwood, once cherished by the night elves as a...",sec={{t="A Forest Turned to Stone",b="Irontree Woods was once a tranquil woodland glade tended by the kaldorei, but the demonic taint of the Burning Legion during the Third War choked the life from its soil. The grove's guardian Ancients—Hastat, Stoma, and Vartrus—succumbed to the dark magic, petrifying into lifeless stone monuments that still stand entombed amid the corrupted brush. Now, maddened treants, vile bog beasts, and tainted water elementals wander the twisted forest floor, striking violently at any travelers who dare approach.",sp=0}},faq={{q="What happened to the giant trees here?",a="The great living trees of the night elves—specifically the Ancients named Hastat, Stoma, and Vartrus—succumbed to the demonic corruption that engulfed Felwood during the Third War. The dark energies petrified them, leaving them frozen as lifeless stone monuments.",al={"why are trees stone","petrified ancients","irontree stone trees"}},{q="Why are the creatures in the woods hostile?",a="The pervasive fel corruption of the Burning Legion has driven the forest's native inhabitants mad. Treants, bog beasts, and water elementals have had their minds and forms twisted, turning them aggressively hostile to any outside presence.",al={"angry treants felwood","corrupted elementals irontree"}},{q="Can Irontree Woods ever recover from the corruption?",a="The grove is profoundly warped, and its guardian Ancients are dead and petrified. Any hope of recovery rests with the druids working to cleanse the demonic corruption that grips all of Felwood.",al={"healing irontree woods","can felwood be saved","new ancient irontree"}},{q="Who used to care for this grove?",a="The night elves and their allied Ancients once protected and tended this glade, as evidenced by the kaldorei stonework, relics, and the petrified guardian trees that remain scattered across northern Felwood.",al={"night elf irontree","who built the statues"}}},ang={["race:NightElf"]="Standing among the petrified husks of Hastat, Stoma, and Vartrus is a bitter reminder of the Third War's toll on your sacred woodlands.",["class:Druid"]="The twisted bog beasts and petrified Ancients show the devastating extent of demonic blight, calling for pure moonwell waters to spark renewal in the tainted soil."},kw={"ancients","felwood","hastat","irontree woods","moonwell","petrified trees","stoma","treants","vartrus"},rel={"zone:felwood","topic:night-elf","topic:burning-legion","subzone:moonwell-ashenvale"},src={"Irontree Woods"}}
E["subzone:jadefire-run"] = {t="subzone",n="Jadefire Run",z="felwood",s="Jadefire Run is a heavily fortified satyr encampment nestled in northern Felwood. It houses some of the most powerful and cunning satyrs in the region, serving as a bastion of demonic corruption deep within the tainted forest.",h="Jadefire Run is a heavily fortified satyr encampment nestled in northern Felwood.",sec={{t="A Bastion of Deceit",b="Situated amid the blighted woods of northern Felwood, Jadefire Run functions as a stronghold for the Jadefire satyrs. Unlike lesser outposts scattered throughout the valley, this camp features substantial demonic construction and shelters formidable spellcasters and tricksters. The satyrs here actively conspire to spread corruption further across Kalimdor, employing dark sorcery and foul trickery against anyone who dares intrude on their territory.",sp=0}},faq={{q="What is Jadefire Run?",a="Jadefire Run is a major satyr settlement located in northern Felwood. It serves as a central redoubt for some of the most dangerous and elite satyrs infesting the forest.",al={"jadefire run info","what is this place felwood"}},{q="Who rules or lives in Jadefire Run?",a="The encampment is occupied by the Jadefire satyrs—corrupted servants of the Burning Legion who wield fel magic and deceptive illusions to terrorize the surrounding forest.",al={"who lives here","jadefire run mobs"}},{q="Why is Jadefire Run so dangerous?",a="The satyrs here are noticeably stronger and more organized than those in southern Felwood. Backed by demonic structures and potent spellcasters, they easily overpower unprepared adventurers.",al={"is jadefire run hard","jadefire run danger"}}},ang={["race:NightElf"]="For the night elves, Jadefire Run is a grotesque reminder of ancient betrayal and demonic defilement that must be cleansed from sacred Kalimdor soil.",["class:Druid"]="Druids view the vile rituals and fel presence festering in Jadefire Run as an open wound poisoning the natural spirits of Felwood."},kw={"corrupted","demons","felwood","jadefire","jadefire run","satyr","xavaric"},rel={"zone:felwood","topic:satyr"},src={"Jadefire Run"}}
E["subzone:jaedenar"] = {t="subzone",n="Jaedenar",z="felwood",s="Jaedenar is a blighted hollow in central Felwood built over ancient night elf ruins and druidic barrow dens. Named in foul homage to the demon lord Kil'jaeden, it serves as the primary base of operations for the Shadow Council in northern Kalimdor. Cultists, warlocks, and summoned demons scour the corrupt hollow, guarding the subterranean descent into the Shadow Hold.",h="Jaedenar is a blighted hollow in central Felwood built over ancient night elf ruins and druidic barrow dens.",sec={{t="A Bastion of Fel Worship",b="Long ago, these hollows sheltered night elf sacred grounds and slumbering druids connected to the Emerald Dream. After the devastation of the Third War, the vile remnant of the Shadow Council laid claim to the valley, christening it Jaedenar to honor the demon lord Kil'jaeden. Warlocks—predominantly renegade orcs and Forsaken—have gathered here alongside satyrs, succubi, and felguards. They occupy both the surface ruins and the deeper barrow dens, twisting what was once holy woodland into a grim center of demonic invocation.",sp=0},{t="The Gates of the Shadow Hold",b="Above ground, the cultists gather at profane sites like the Shrine of the Deceiver, burning braziers of fell flame and conducting rituals to further corrupt the timberland. Beneath the surface lies the entrance to the Shadow Hold, the subterranean stronghold where the council's true masters direct their operations across Felwood. The Emerald Sanctuary watches the festering enclave with profound concern, regularly enlisting daring wanderers to disrupt their summoning circles and douse the dark flames that seal their tunnels.",sp=0}},faq={{q="What is Jaedenar named after?",a="Jaedenar was named by the Shadow Council in worship of Kil'jaeden the Deceiver, one of the supreme commanders of the Burning Legion.",al={"jaedenar name origin","why is it called jaedenar","jaedenar namesake"}},{q="Who controls Jaedenar?",a="The stronghold is held by the Shadow Council, an insidious cabal of mortal warlocks—chiefly orcs and Forsaken—who serve the demonic will of the Burning Legion alongside summoned fiends and corrupted satyrs.",al={"who runs jaedenar","jaedenar faction","enemies in jaedenar"}},{q="What was here before the demons arrived?",a="Before the Third War, the area consisted of ancient night elf architecture and peaceful druidic barrow dens where druids once rested while roaming the Emerald Dream.",al={"jaedenar history","who lived in jaedenar","jaedenar barrow dens"}},{q="What is the Shadow Hold?",a="The Shadow Hold is the subterranean cavern system beneath Jaedenar. Formerly druidic barrow dens, it now functions as the fortified headquarters of the Shadow Council's leadership in Felwood.",al={"what is shadow hold","cave in jaedenar","underground jaedenar"}}},ang={["class:Druid"]="Jaedenar is a tragic desecration of sacred ground; its barrows, once peaceful sanctuaries for communion with the Emerald Dream, are now drowned in demonic ichor.",["class:Warlock"]="The warlocks of Jaedenar represent the Shadow Council's enduring presence on Azeroth, openly summoning powerful demons and wielding volatile fel sorcery."},kw={"barrow dens","deceiver","felwood","jaedenar","kil'jaeden","shadow council","shadow hold"},rel={"zone:felwood","subzone:shadow-hold","topic:shadow-council","npc:greta-mosshoof","topic:emerald-dream","topic:satyr","topic:druid","topic:forsaken"},src={"Jaedenar"}}
E["subzone:morlos-aran"] = {t="subzone",n="Morlos'Aran",z="felwood",s="Morlos'Aran is an ancient night elf ruin nestled in the southern reaches of Felwood. Once a proud and thriving settlement before the Great Sundering, it now stands as a grim monument to a lost golden age, drowned under the demonic blight that plagues the surrounding forest.",h="Morlos'Aran is an ancient night elf ruin nestled in the southern reaches of Felwood.",sec={{t="Echoes of the Golden Age",b="Ten thousand years ago, prior to the Sundering, Morlos'Aran was a grand urban center of the ancient kaldorei civilization. Much like sister settlements such as Ameth'Aran, Bashal'Aran, and Ordil'Aran across northern Kalimdor, its marble arches and moonlit plazas bustled with elven life and arcana. When the Well of Eternity collapsed, the city broke, leaving only shattered colonnades behind as monuments to their civilization's zenith.",sp=0},{t="A Blighted Relic",b="While neighboring ruins in Darkshore and Ashenvale fell to decay and wilderness, Morlos'Aran met a far grimmer fate during the Third War. Positioned directly within the corridor trampled by the Burning Legion, its surviving foundations were choked by demonic corruption and toxic mire. Today, the ruins are haunted by wandering beasts, corrupted elementals, and remnants of the shadow forces lingering in Felwood.",sp=0}},faq={{q="What was Morlos'Aran originally?",a="It was a major night elf settlement that thrived before the Great Sundering. Along with sister cities across ancient Kalimdor, it formed part of the core civilization of the kaldorei golden age before falling into ruin ten thousand years ago.",al={"what is morlos aran","morlos'aran history","who built morlos aran"}},{q="Why does the name end in ''Aran'?",a="The suffix appears in several pre-Sundering night elf cities, including Ameth'Aran and Bashal'Aran in Darkshore, Ordil'Aran in Ashenvale, and Tethris'Aran in Desolace. It denotes settlements built during the ancient empire.",al={"meaning of aran","aran suffix","ameth aran connection"}},{q="Where exactly is Morlos'Aran located?",a="It lies in the southern portion of Felwood, near the border crossing from Ashenvale. Its crumbling marble architecture stands visible among the corrupted, withered trees just off the main path.",al={"morlos aran location","where is morlos'aran","finding morlos aran"}},{q="What threats wander these ruins today?",a="Corrupted wildlife, tainted treants, and lingering demonic spawn infest the surrounding forest and make Morlos'Aran extremely hazardous for passing travelers heading north into Felwood.",al={"what is inside morlos'aran","morlos aran mobs","dangers of morlos aran"}}},ang={["race:NightElf"]="Passing through Morlos'Aran offers a tragic reminder of how far the empire fell, seeing sacred ancestral stonework now swallowed by the foul demonic corruption of the Legion.",["class:Druid"]="The twisted earth around the ruined foundations illustrates the extreme damage inflicted upon Felwood, spurring Cenarion efforts to purify the land."},kw={"ameth'aran","bashal'aran","felwood","kaldorei","morlos aran","morlos'aran","ruins","sundering"},rel={"zone:felwood","subzone:ameth-aran","quest:954","zone:ashenvale","zone:darkshore","zone:desolace","topic:night-elf"},src={"Morlos'Aran"}}
E["subzone:ruins-of-constellas"] = {t="subzone",n="Ruins of Constellas",z="felwood",s="The Ruins of Constellas are the shattered remnants of an ancient night elf settlement in Felwood, nestled near the roots of Mount Hyjal. Today, the once-sacred grounds are overrun by the Jadefire satyrs, who have violently profaned the settlement's moonwell with demonic fel magic.",h="The Ruins of Constellas are the shattered remnants of an ancient night elf settlement in Felwood, nestled...",sec={{t="A Defiled Sanctuary",b="The classical stone arches and crumbling plazas of Constellas reveal that this was once an idyllic night elven community. During the Third War, the Burning Legion's march through Felwood shattered the haven, leaving it exposed to lingering demonic corruption. Now, the foul Jadefire satyrs hold dominion over the stones. Led by Xavathras, they actively tend to a defiled moonwell, transforming pure waters into a font of noxious fel power on behalf of their master, Lord Xavaric.",sp=0},{t="The Struggle for Cleansing",b="The defilement of Constellas has provoked active resistance from Kalimdor's defenders. Druidic Emerald Bearkin battle the satyrs throughout the ruins in an attempt to reclaim the forest, while night elven investigators observe from a nearby camp to the southeast. To protect their foul rituals and prevent intruders from reaching Xavathras, the satyrs have sealed the deeper pathways into the ruins behind an impenetrable wall of magical fire.",sp=0}},faq={{q="What was Constellas before the corruption?",a="Constellas was an ancient night elf settlement near the base of Mount Hyjal. Its architecture and moonwell indicate it served as a serene grove dedicated to Elune and nature before the Burning Legion invaded the forest during the Third War.",al={"constellas history","what was constellas","who built constellas"}},{q="Who controls the ruins now?",a="The ruins are occupied by the Jadefire satyrs, led on-site by Xavathras. They cultivate demonic energies throughout the area under the overarching commands of Lord Xavaric.",al={"who lives here","who rules constellas","jadefire satyrs constellas"}},{q="What happened to the moonwell in Constellas?",a="The moonwell was seized by the Jadefire satyrs and corrupted with fel magic. Instead of channeling the soothing blessings of Elune, it has been twisted into a toxic source of fel energy cultivated by Xavathras.",al={"corrupted moonwell felwood","constellas moonwell","why is the well green"}},{q="Why is there a wall of fire inside the ruins?",a="The satyrs erected a blazing barrier across the inner path to safeguard Xavathras and protect their ongoing rituals from retaliating druids and Emerald Bearkin.",al={"constellas fire wall","fire barrier constellas","how to get past fire wall"}}},ang={["race:NightElf"]="The desecration of Constellas and its corrupted moonwell is an egregious affront to Elune, demanding that night elves drive out the Jadefire satyrs.",["class:Druid"]="Watching Emerald Bearkin fight against demonic occupiers makes Constellas a stark reminder of the druidic vow to restore balance to Felwood."},kw={"bearkin","constellas","felwood","jadefire","moonwell","satyr","xavaric","xavathras"},rel={"zone:felwood","npc:xavathras","topic:satyr","topic:night-elf","topic:druid","subzone:moonwell-ashenvale"},src={"Ruins of Constellas"}}
E["subzone:shadow-hold"] = {t="subzone",n="Shadow Hold",z="felwood",s="Shadow Hold is a sprawling subterranean complex hidden within the blighted canyon of Jaedenar in western Felwood. Once a sacred night elf barrow den, it has been seized and desecrated by the Shadow Council to serve as their primary bastion on Kalimdor.",h="Shadow Hold is a sprawling subterranean complex hidden within the blighted canyon of Jaedenar in western...",sec={{t="A Defiled Sanctuary",b="Beneath the corrupted red earth of Jaedenar lies Shadow Hold, a vast underground labyrinth carved out of what was once an ancient night elf barrow den. Where sleeping druids once rested to tend the Emerald Dream, dark warlocks and demonic servitors now stalk twisted corridors illuminated by fel fire. At its deepest tiers, the cult commands a formidable force under the dreadlord Lord Banehollow, Prince Xavalis, and Shadow Lord Fel'dan, making it the supreme seat of demonic influence in the region.",sp=0},{t="Horrors in the Deep",b="The Shadow Council uses the caverns to coordinate their corruption of Felwood and conduct brutal interrogations. Alliance scouts, including the night elf Arko'narin Starshade and the human paladin Trey Lightforge, fell into cultist hands deep inside the hold. While Arko'narin survived through timely rescue, Trey was tortured to death by the cult's torturers, his spirit briefly twisted into malice before being laid to rest. The Emerald Circle and local shamans work constantly to pierce the dark barriers shielding the hold in hopes of striking down its demonic masters.",sp=1}},faq={{q="What was Shadow Hold before the Shadow Council took it over?",a="Shadow Hold was originally an ancient night elf barrow den, dedicated to the slumbering druids who tended the land and communion with the Emerald Dream. Following the Third War and the demonic corruption of Felwood, the Shadow Council seized the underground complex and desecrated its sacred halls into a fel fortress.",al={"shadow hold history","who built shadow hold","what was shadow hold originally"}},{q="Who rules inside Shadow Hold?",a="The stronghold is overseen by the dreadlord Lord Banehollow, alongside powerful lieutenants including the satyr Prince Xavalis and the warlock Shadow Lord Fel'dan, who commands the mortal cultists.",al={"shadow hold boss","who is in charge of shadow hold","leaders of shadow hold"}},{q="Why would an adventurer infiltrate Shadow Hold peacefully?",a="Practitioners of the dark arts seeking powerful summoning reagents, such as Xorothian Stardust, sometimes enter the hold disguised as loyal Shadow Council cultists. Lord Banehollow allows trade with outsiders only if they prove their loyalty by rooting out spies and traitors within his ranks.",al={"infiltrate shadow hold","shadow council disguise shadow hold","xorothian stardust shadow hold"},sp=1},{q="What happened to the captives in the hold?",a="The night elf Arko'narin Starshade and the paladin Trey Lightforge were captured while scouting the Shadow Council. Trey was tortured to death by the cultist Rakaiah, while Arko'narin was rescued from her cage by adventurers, who later recovered Trey's remains for a proper burial.",al={"jaedenar prisoners","trey lightforge and arkonarin","shadow hold cage"},sp=1}},ang={["class:Warlock"]="The deepest recesses of Shadow Hold house rare demonic reagents like Xorothian Stardust, obtainable only by winning the favor of Lord Banehollow through cunning infiltration.",["race:NightElf"]="The hold is a horrifying sight for night elves—an ancestral barrow den defiled with fel sludge, imprisonment cages, and demonic rituals."},kw={"arko'narin","banehollow","barrow den","fel'dan","felwood","jaedenar","shadow council","shadow hold","trey lightforge"},rel={"subzone:jaedenar","zone:felwood","topic:shadow-council","npc:greta-mosshoof","npc:islen-waterseer","topic:satyr","topic:night-elf","topic:druid"},src={"Shadow Hold"}}
E["subzone:shatter-scar-vale"] = {t="subzone",n="Shatter Scar Vale",z="felwood",s="Shatter Scar Vale is a scorched basin in central Felwood, located just north of Bloodvenom Falls. It marks the ground zero where demonic infernals crashed into northern Kalimdor during the Third War. Today, the craters still burn with fel fire and host lingering remnants of the Burning Legion.",h="Shatter Scar Vale is a scorched basin in central Felwood, located just north of Bloodvenom Falls.",sec={{t="Impact of the Infernals",b="During the Third War, the Burning Legion rained living siege engines down upon northern Kalimdor. Shatter Scar Vale bore the brunt of this celestial assault. Demonic infernals plummeted from the skies, tearing through the ancient canopy and smashing deep craters into the earth. The violent impact shattered the terrain, leaving blackened hollows that smolder with unholy fire to this day. Though the Legion was shattered at Mount Hyjal, the infernals and lingering lesser demons never truly dispersed, maintaining an entrenched foothold in the scarred earth.",sp=0}},faq={{q="Why is the ground covered in craters?",a="The craters were formed during the Third War when the Burning Legion bombarded the forest with infernals. These hulking constructs of fel stone plummeted from the sky like meteors, smashing into the ground and leaving smoldering impact scars across the valley.",al={"craters in felwood","why is shatter scar vale cratered","what made the craters"}},{q="What creatures roam Shatter Scar Vale?",a="The vale remains overrun by constructs and servants of the Burning Legion. Living infernals still guard the smoldering impact basins, alongside other wandering lesser demons left behind after the invasion faltered.",al={"what mobs are here","shatter scar vale enemies"}},{q="Where is Shatter Scar Vale located?",a="Shatter Scar Vale lies in the central reaches of Felwood, positioned directly north of Bloodvenom Falls along the eastern side of the forest's main path.",al={"shatter scar vale location","where is shatter scar vale"}}},ang={["class:Warlock"]="The fel-infused cores of the infernals roaming these craters represent potent conduits of chaotic magic left behind from the Legion's invasion.",["class:Druid"]="The smoldering scars in this vale are persistent open wounds on Kalimdor's spirit, refusing to heal while the Legion's constructs still burn."},kw={"bloodvenom falls","burning legion","craters","felwood","infernals","shatter scar vale"},rel={"zone:felwood","topic:burning-legion","subzone:bloodvenom-falls","topic:third-war"},src={"Shatter Scar Vale"}}
E["subzone:talonbranch-glade"] = {t="subzone",n="Talonbranch Glade",z="felwood",s="Talonbranch Glade is a quiet night elf redoubt nestled in the blighted hills of northern Felwood. Located just south of Timbermaw Hold, it provides a rare haven of pristine moonlight, sanctuary, and hippogryph transit in an otherwise corrupted wilderness.",h="Talonbranch Glade is a quiet night elf redoubt nestled in the blighted hills of northern Felwood.",sec={{t="A Beacon in the Blight",b="Perched on high ground near the tunnel to Timbermaw Hold, Talonbranch Glade serves as the northernmost bastion of the Alliance in Felwood. Centered around a sheltered night elf lodge and a functioning moonwell, the outpost offers a crucial refuge from the demonic corruption that has swallowed the surrounding forest. Alliance scouts, Sentinels, and passing adventurers use the glade to rest, recover, and plan their excursions deeper into the tainted woods or onward toward Winterspring and Moonglade.",sp=0},{t="A Crossroads of the North",b="Aside from its natural and spiritual defenses, Talonbranch Glade functions as an essential logistics hub. Hippogryphs stationed here connect travelers to Auberdine in Darkshore and Everlook in the snowy expanse beyond Timbermaw Hold. It remains a lonely, vigilant watchpost holding the line against the encroaching shadows of the Shadow Council and feral beast packs roaming the corrupted vales.",sp=0}},faq={{q="What is Talonbranch Glade?",a="It is an Alliance encampment in northern Felwood, serving as a haven, rest stop, and flight hub for Sentinels, druids, and travelers traversing the corrupted forest.",al={"talonbranch","talonbranch purpose","what is this place"}},{q="Where does the flight master here fly to?",a="The hippogryph master at Talonbranch connects directly to several Alliance and neutral outposts, including Auberdine, Everlook, and Moonglade.",al={"talonbranch flight paths","flight points","where can i fly"}},{q="Is the water in the moonwell safe to drink?",a="Yes. Unlike the tainted pools and corrupt springs scattered throughout Felwood, the moonwell at Talonbranch Glade remains blessed by Elune and untainted by demonic filth.",al={"talonbranch moonwell","is the water clean","moonwell corrupted"}},{q="How close is this to Timbermaw Hold?",a="Talonbranch Glade sits directly south of the entrance to Timbermaw Hold, making it the final resting place before navigating the furbolg tunnels into Winterspring or Moonglade.",al={"where is timbermaw hold","path to winterspring"}}},ang={["faction:Alliance"]="Talonbranch Glade is your northernmost operational outpost in Felwood, offering vital flight connections, repairs, and sanctuary near Timbermaw Hold.",["race:NightElf"]="The glade's untouched moonwell serves as a testament to Elune's enduring grace amid the severe demonic blight choking the ancient forest."},kw={"felwood","flight point","glade","moonwell","sentinels","talonbranch","timbermaw"},rel={"zone:felwood","subzone:timbermaw-hold","subzone:emerald-sanctuary","subzone:everlook","subzone:auberdine","topic:alliance","topic:elune"},src={"Talonbranch Glade"}}
E["zone:felwood"] = {t="zone",n="Felwood",z="felwood",s="Felwood is a blighted forest nestled between Ashenvale and Mount Hyjal, deeply poisoned by demonic magic during the Third War. Once a lush paradise of meadows and groves tended by the night elves, it now crawls with demonic satyrs, slavering beasts, and twisted ancients. Cenarion Circle druids, alongside outposts of the Alliance and Horde, desperately work to cleanse the land and purge the Shadow Council from its depths.",h="Felwood is a blighted forest nestled between Ashenvale and Mount Hyjal, deeply poisoned by demonic magic...",sec={{t="A Paradise Befouled",b="Before the Third War, this valley was a peaceful haven of singing birds, clear streams, and tranquil groves guarded by ancient protectors. That ended when the dreadlord Tichondrius and the Burning Legion deployed the Skull of Gul'dan to poison northern Kalimdor ahead of their assault on Mount Hyjal. The skull's vile sorceries twisted the forest floor into a blackened mire. Though Illidan Stormrage eventually slew Tichondrius and consumed the artifact's essence, the land remained steeped in fel corruption. Mighty treants and ancients rotted from within, rivers turned to boiling bile, and the forest's beasts were driven into cannibalistic madness.",sp=0},{t="The War for Cleansing",b="Healing Felwood has proven agonizingly slow. At the Emerald Sanctuary along the southern border, the Cenarion Circle wages an uphill battle against the blighted corruption. Druids equip wanderers with Cenarion beacons and cleansing salves, laboring to heal poisoned plants like songflowers and night dragon bulbs. Both factions maintain footholds in the tainted wilds—the night elves at Talonbranch Glade in the north and the Horde at Bloodvenom Post. These outposts serve as fragile bulwarks amid a deadly wilderness where nature has turned against all mortal flesh.",sp=0},{t="The Shadow in Jaedenar",b="The lingering fel taint is actively nurtured by dark cultists. Within the subterranean labyrinth of Jaedenar and Shadow Hold, remnants of the Shadow Council conduct foul rituals under the direction of Lord Banehollow. Allied with deceitful satyrs who desecrate ancient moonwells, these warlocks harvest the forest's agony and summon forth demonic reinforcements. Any lasting hope of redeeming Felwood requires tearing this insidious council out by its roots.",sp=1}},faq={{q="Why is Felwood corrupted?",a="During the Third War, the dreadlord Tichondrius used the demonic artifact known as the Skull of Gul'dan to corrupt the forest. This was intended to weaken the night elves' defenses during the Burning Legion's march toward Mount Hyjal, blighting the wildlife, water, and ancients.",al={"how did felwood get corrupted","what happened to felwood","why are the trees dead"}},{q="Can the corrupted plants in the forest be cleansed?",a="Yes. Druids of the Cenarion Circle provide adventurers with salves brewed from collected fel taints and mineral residues. Applying these salves to plants like songflowers, whiplash tubers, and night dragons purges their corruption and yields potent restorative fruit and blessings.",al={"how to cleanse plants","cenarion plant salve","corrupted songflower"}},{q="Who controls Jaedenar?",a="Jaedenar is held by the Shadow Council, a clandestine sect of mortal warlocks and demon worshippers. From deep within the subterranean caverns of Shadow Hold, the dreadlord Lord Banehollow oversees their dark rituals and commands the satyrs inhabiting the region.",al={"what is jaedenar","who is in shadow hold","jaedenar boss"}},{q="Are the furbolgs in Felwood hostile?",a="Most are hostile. Tribes such as the Deadwood have completely succumbed to demonic corruption and fel madness. However, the Timbermaw tribe holding the northern tunnel network remains uncorrupted, though they are deeply distrustful of outsiders until proven friendly.",al={"felwood furbolgs","timbermaw furbolgs","deadwood village"}},{q="How do you get to Moonglade or Winterspring through Felwood?",a="The road leads north directly into Timbermaw Hold, a fortified cavern complex. The uncorrupted Timbermaw furbolgs control the tunnels connecting Felwood to Moonglade and Winterspring. Travelers must either earn their trust or fight their way through.",al={"timbermaw tunnel","road to winterspring","pass to moonglade"}},{q="Why do the corrupted ancients attack night elves?",a="The once-noble ancients and treants were warped and poisoned by demonic magic. Bound in eternal agony, their shattered minds harbor deep resentment toward the night elves, whom they perceive as having abandoned them to the Burning Legion.",al={"mad treants","corrupted ancients","why ancients hostile"}}},ang={["class:Druid"]="Felwood is a profound tragedy for the Cenarion Circle, where druids dedicate their lives to cleansing blighted plants and calming maddened nature spirits.",["race:NightElf"]="The desecration of these ancient woods is a source of immense grief and shame for the kaldorei, who failed to protect them from the Legion's touch.",["class:Warlock"]="The dark tunnels of Jaedenar and the lingering demonic forces make Felwood a focal point for hunting rival cultists of the Shadow Council.",["profession:Herbalism"]="The fel-soaked earth yields rare and volatile flora, serving as one of the few places in Azeroth to gather Gromsblood and Arthas' Tears."},kw={"banehollow","bloodvenom","deadwood","emerald sanctuary","felwood","jaedenar","songflower","talonbranch","tichondrius","timbermaw"},rel={"subzone:emerald-sanctuary","subzone:jaedenar","subzone:timbermaw-hold","subzone:talonbranch-glade","subzone:bloodvenom-post","topic:cenarion-circle","topic:shadow-council","zone:ashenvale"},src={"Felwood (Classic)","Felwood"}}
